  ["gOakSpeech_Text_AskPlayerGender"] = "Agora me diga. Você é um garoto?\\nOu você é uma garota?",
  ["gOakSpeech_Text_ConfirmRivalName"] = "… Hmm, era {RIVAL}?",
  ["gOakSpeech_Text_IStudyPokemon"] = "Para algumas pessoas, os POKéMON\\nsão mascotes. Já outras usam eles\\lpara batalhar.\\pQuanto a mim…\\pEu estudo os POKéMON como\\nprofissão.\\p",
  ["gOakSpeech_Text_IsInhabitedFarAndWide"] = "… é habitado por criaturas chamadas\\nde POKéMON.\\p",
  ["gOakSpeech_Text_LetsGo"] = "{PLAYER}!\\pSua própria lenda POKéMON está\\nprestes a começar!\\pUm mundo de sonhos e aventuras com\\nPOKéMON espera por você! Vamos lá!",
  ["gOakSpeech_Text_RememberRivalsName"] = "Isso mesmo! Agora me lembrei!\\nO nome dele é {RIVAL}!\\p",
  ["gOakSpeech_Text_SoYourNameIsPlayer"] = "Certo…\\nEntão o seu nome é {PLAYER}.",
  ["gOakSpeech_Text_TellMeALittleAboutYourself"] = "Mas antes, me fale um pouco sobre\\nvocê.\\p",
  ["gOakSpeech_Text_ThisWorld"] = "Este mundo…",
  ["gOakSpeech_Text_WelcomeToTheWorld"] = "Olá!\\nPrazer em te conhecer!\\pBoas-vindas ao mundo de POKéMON!\\pO meu nome é CARVALHO.\\pAs pessoas carinhosamente me\\nchamam de PROFESSOR POKéMON.\\p",
  ["gOakSpeech_Text_WhatWasHisName"] = "Este é o meu neto.\\pEle tem sido o seu rival desde\\nque vocês dois eram bebês.\\p… Hmm, qual era mesmo o nome dele?",
  ["gOakSpeech_Text_YourNameWhatIsIt"] = "Vamos começar pelo seu nome.\\nComo se chama?\\p",
  ["gOakSpeech_Text_YourRivalsNameWhatWasIt"] = "O nome do seu rival, qual era mesmo?",
